  "buscar": "amp-kgr-09.14 · l20-09-14 · vladimir ussachevsky · programas del claem · programa · folleto volante · 10 de junio de 1968, 19:45 h · sala del centro de experimentacion audiovisual – itdt (florida 936, buenos aires) · claem · vladimir ussachevsky. obras musicales electronicas y musica electronica para una pelicula · memoria y balance 1968 la musica en el di tella vladimir ussachevsky: electronic and acoustic works 1957-1972 · la memoria de 1968 denomina retrospectivamente el acto homenaje a vladimir ussachevsky y lo describe como conferencia y exhibicion de line of apogee. el curso visitante mis experiencias en los estudios de musica electronica aparece en la memoria como actividad separada del homenaje; no corresponde fusionarlo con e114. vladimir ussachevsky: obras musicales electronicas y musica electronica para una pelicula se presento el lunes 10 de junio de 1968 a las 19:45. sala de experimentacion audiovisual del instituto torcuato di tella, florida 936, buenos aires. ussachevsky estuvo a cargo de los comentarios; el programa musical incluyo of wood and brass, computer piece y creation: prologue, con las dos ultimas marcadas como primera audicion. la segunda parte proyecto line of apogee, pelicula escrita, producida y dirigida por lloyd michael williams, con banda sonora electronica de ussachevsky; el programa la marca como estreno en buenos aires. las obras senaladas fueron producidas en el columbia-princeton electronic music center; computer piece fue preparada en bell telephone laboratories, new jersey.",
